return ['domain'=>'dosieci-translator','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'DoSieci Translator 1.0.0','pot-creation-date'=>'2026-09-24T20:24:12+00:00','po-revision-date'=>'2026-09-24T20:24:12+00:00','messages'=>['DoSieci Translator'=>'DoSieci Translator','https://dosieci.pl/wtyczki/translator-woocommerce/'=>'https://dosieci.pl/wtyczki/translator-woocommerce/','Translate the title, short description or description of WooCommerce products, posts and pages with DeepL, using your own API key. Always previewed before saving, and the previous text can be restored with one click.'=>'Tłumaczenie tytułu, krótkiego opisu lub opisu produktów WooCommerce, wpisów i stron przez DeepL na Twoim własnym kluczu API. Zawsze z podglądem przed zapisem, a poprzedni tekst można przywrócić jednym kliknięciem.','DoSieci'=>'DoSieci','https://dosieci.pl/'=>'https://dosieci.pl/','Unsupported target language.'=>'Nieobsługiwany język docelowy.','Arabic'=>'arabski','Bulgarian'=>'bułgarski','Czech'=>'czeski','Danish'=>'duński','German'=>'niemiecki','Greek'=>'grecki','English (British)'=>'angielski (brytyjski)','English (American)'=>'angielski (amerykański)','Spanish'=>'hiszpański','Estonian'=>'estoński','Finnish'=>'fiński','French'=>'francuski','Hebrew'=>'hebrajski','Hungarian'=>'węgierski','Indonesian'=>'indonezyjski','Italian'=>'włoski','Japanese'=>'japoński','Korean'=>'koreański','Lithuanian'=>'litewski','Latvian'=>'łotewski','Norwegian (Bokmål)'=>'norweski (bokmål)','Dutch'=>'niderlandzki','Polish'=>'polski','Portuguese (Brazilian)'=>'portugalski (brazylijski)','Portuguese (European)'=>'portugalski (europejski)','Romanian'=>'rumuński','Russian'=>'rosyjski','Slovak'=>'słowacki','Slovenian'=>'słoweński','Swedish'=>'szwedzki','Thai'=>'tajski','Turkish'=>'turecki','Ukrainian'=>'ukraiński','Vietnamese'=>'wietnamski','Chinese (simplified)'=>'chiński (uproszczony)','Chinese (traditional)'=>'chiński (tradycyjny)','DeepL rejected the API key. Check the key; keys ending in ":fx" are DeepL API Free keys.'=>'DeepL odrzucił klucz API. Sprawdź klucz; klucze kończące się na „:fx” to klucze DeepL API Free.','Too many requests to DeepL. Wait a moment and try again.'=>'Zbyt wiele zapytań do DeepL. Odczekaj chwilę i spróbuj ponownie.','The character limit of your DeepL plan is used up for this billing period.'=>'Wyczerpano limit znaków w Twoim planie DeepL na ten okres rozliczeniowy.','The text is too long for a single DeepL request. Split the content into smaller parts.'=>'Tekst jest za długi na jedno zapytanie do DeepL. Podziel treść na mniejsze części.','DeepL is temporarily unavailable. Try again in a moment.'=>'DeepL jest chwilowo niedostępny. Spróbuj ponownie za chwilę.','DeepL returned HTTP error %d.'=>'DeepL zwrócił błąd HTTP %d.','The DeepL response contains no translation.'=>'Odpowiedź DeepL nie zawiera tłumaczenia.','The DeepL response has an unexpected format.'=>'Odpowiedź DeepL ma nieoczekiwany format.','Translator'=>'Translator','Translate'=>'Przetłumacz','Open'=>'Otwórz','You do not have permission to do this.'=>'Nie masz uprawnień do wykonania tej operacji.','The DeepL key was removed.'=>'Klucz DeepL został usunięty.','Enter a DeepL API key.'=>'Wpisz klucz API DeepL.','That does not look like a DeepL API key. Paste only the key from your DeepL account.'=>'To nie wygląda na klucz API DeepL. Wklej sam klucz ze swojego konta DeepL.','The DeepL key was saved.'=>'Zapisano klucz DeepL.','Save your DeepL API key first.'=>'Najpierw zapisz swój klucz API DeepL.','The translation is ready to review below. Nothing has been saved yet.'=>'Tłumaczenie jest gotowe do sprawdzenia poniżej. Nic jeszcze nie zostało zapisane.','The item was not found, or you cannot edit it.'=>'Nie znaleziono elementu albo nie możesz go edytować.','The preview has expired. Translate the text again.'=>'Podgląd wygasł. Przetłumacz tekst ponownie.','The text was changed after the preview was made, so the translation was not saved. Translate it again.'=>'Tekst zmienił się po utworzeniu podglądu, dlatego tłumaczenie nie zostało zapisane. Przetłumacz go ponownie.','The translation was saved. You can restore the previous text below.'=>'Tłumaczenie zostało zapisane. Poprzedni tekst możesz przywrócić poniżej.','There is nothing to restore for this field.'=>'Dla tego pola nie ma czego przywracać.','The previous text was restored.'=>'Przywrócono poprzedni tekst.','Choose a field and a target language.'=>'Wybierz pole i język docelowy.','This field is empty, there is nothing to translate.'=>'To pole jest puste — nie ma czego tłumaczyć.','You do not have permission to access this page.'=>'Nie masz uprawnień do tej strony.','Title'=>'Tytuł','Excerpt / short description'=>'Zajawka / krótki opis','Content / description'=>'Treść / opis','Translates one field at a time and replaces its text after you approve the preview. It does not create a second language version of the page. Requests go from this site straight to DeepL with your own key, never through DoSieci.'=>'Tłumaczy jedno pole na raz i podmienia jego tekst po zatwierdzeniu podglądu. Nie tworzy drugiej wersji językowej strony. Zapytania idą z tej witryny bezpośrednio do DeepL na Twoim kluczu, nigdy przez DoSieci.','Translate a field'=>'Przetłumacz pole','Tip: use the "Translate" link under any post, page or product in its list.'=>'Wskazówka: użyj linku „Przetłumacz” pod dowolnym wpisem, stroną lub produktem na liście.','Post, page or product ID'=>'ID wpisu, strony lub produktu','(no title)'=>'(bez tytułu)','Edit'=>'Edytuj','Field'=>'Pole','Translate into'=>'Przetłumacz na','DeepL detects the source language by itself.'=>'DeepL sam rozpoznaje język źródłowy.','Preview the translation'=>'Pokaż podgląd tłumaczenia','Preview'=>'Podgląd','Field: %1$s. Into: %2$s. Detected source language: %3$s. Nothing has been saved yet.'=>'Pole: %1$s. Na: %2$s. Rozpoznany język źródłowy: %3$s. Nic jeszcze nie zostało zapisane.','Before'=>'Przed','After'=>'Po','Save the translation'=>'Zapisz tłumaczenie','The current text is kept, so you can restore it with one click.'=>'Obecny tekst zostanie zachowany, więc przywrócisz go jednym kliknięciem.','Your DeepL API key'=>'Twój klucz API DeepL','Translations use your own DeepL API key and your own character allowance. Both DeepL API Free and Pro keys work; the right endpoint is picked automatically.'=>'Tłumaczenia korzystają z Twojego klucza API DeepL i Twojego limitu znaków. Działają klucze DeepL API Free i Pro — właściwy endpoint jest wybierany automatycznie.','DeepL API key'=>'Klucz API DeepL','Remove the saved key'=>'Usuń zapisany klucz','Save'=>'Zapisz','Only an administrator can set the DeepL key.'=>'Klucz DeepL może ustawić wyłącznie administrator.','Restore the text from before a translation'=>'Przywróć tekst sprzed tłumaczenia','Kept on %1$s, before translating into %2$s.'=>'Zachowany %1$s, przed tłumaczeniem na: %2$s.','Restore'=>'Przywróć']];